import { GroundedNote } from "../personas/grounded-note";
import { NoteEvidenceList } from "../personas/note-evidence-list";
import {
  $,
  useComputed$,
  component$,
  sync$,
  type PropFunction,
} from "@qwik.dev/core";
import { renderMarkdown } from "../../utils/markdown";
import { revealQuoteFromEvent } from "../../utils/quote-grounding";
import { SpeakButton } from "../ui/speak-button";
import { PersonaPortrait } from "../personas/persona-portrait";
import { EditorialActivity } from "../ui/editorial-activity";
import type { NotePopover } from "./editor-state";
import { openLiveVoice } from "../../utils/live-voice-workspace";
import { stopSpeech } from "../../utils/speech";
import {
  CardBust,
  CardMenu,
  CardNotice,
  CloseIcon,
  ExpandIcon,
  MicIcon,
  openFullThread,
  SendIcon,
  useSpeechError,
} from "./card-parts";

interface PersonaNotePanelProps {
  note: NotePopover | null;
  onPin$: PropFunction<(noteId: string) => void>;
  onClose$: PropFunction<() => void>;
  onReply$: PropFunction<
    (noteId: string, text: string, author: string) => void
  >;
  onStrike$: PropFunction<(noteId: string) => void>;
  onDismissError$?: PropFunction<(noteId: string) => void>;
}

/** A reply that landed this recently gets the arrival pulse. */
const FRESH_REPLY_MS = 2500;

/**
 * The anchored conversation with a persona about one marked passage.
 *
 * Two stacked boxes: the persona's engraving stands on the first, which
 * holds the note and the thread; the second is the reply. The face and the
 * card's colour already say who is speaking, and the marked passage sits
 * beside the card, so no name, role, label or quote repeats here.
 */
export const PersonaNotePanel = component$<PersonaNotePanelProps>((props) => {
  const note = props.note;
  const onPin$ = props.onPin$;
  const onClose$ = props.onClose$;
  const onReply$ = props.onReply$;
  const onStrike$ = props.onStrike$;
  const onDismissError$ = props.onDismissError$;
  const speechId = `note-popover-${note?.id ?? ""}`;
  /** Why this note would not read aloud, while that is still the case. */
  const speechError = useSpeechError(
    useComputed$(() => `note-popover-${props.note?.id ?? ""}`),
  );
  // Enter sends and Shift+Enter breaks the line, as in every chat box.
  const holdEnter = sync$((event: KeyboardEvent) => {
    if (event.key === "Enter" && !event.shiftKey && !event.isComposing)
      event.preventDefault();
  });

  if (!note) return null;

  const streaming = note.replying && !!note.streamingReply.trim();
  const now = Date.now();
  const lastId = note.thread.at(-1)?.id;

  return (
    <div
      class={[
        "persona-note-card twyne-card manuscript-comment-card",
        { "is-in-margin": !!note.margin },
      ]}
      data-margin-item={note.margin ?? undefined}
      role="dialog"
      aria-label={`Note from ${note.author}`}
      style={{
        left: `${note.x}px`,
        top: note.top != null ? `${note.top}px` : "auto",
        bottom: note.bottom != null ? `${note.bottom}px` : "auto",
        "max-height": `${note.maxH}px`,
        width: note.width ? `${note.width}px` : undefined,
        "--comment-color": note.color,
      }}
      onClick$={(event) => {
        event.stopPropagation();
        if (!note.pinned) onPin$(note.id);
      }}
      onMouseLeave$={(event) => {
        if (note.pinned || note.replying || note.thread.length > 0) return;
        const related = (event as MouseEvent)
          .relatedTarget as HTMLElement | null;
        if (related?.closest(".twyne-persona-note")) return;
        if (related?.closest(".twyne-mark-anchor")) return;
        onClose$();
      }}
    >
      <section class="persona-note__note">
        <div class="persona-note__head">
          <CardBust
            name={note.author}
            activity={note.replying ? "writing" : undefined}
          />
          <div class="persona-note__tools">
            <button
              type="button"
              class="persona-note__tool persona-note__tool--talk focus-ring"
              aria-label={`Talk with ${note.author} about this note`}
              title={`Talk with ${note.author}`}
              onClick$={() => openLiveVoice(note.author, note.note)}
            >
              <MicIcon />
            </button>
            <span class="persona-note__tool">
              <SpeakButton
                inheritColor
                id={speechId}
                text={note.note}
                author={note.author}
                label={note.author}
              />
            </span>
            <CardMenu>
              <button
                type="button"
                role="menuitem"
                class="focus-ring"
                onClick$={() => onStrike$(note.id)}
              >
                Strike — mark as addressed
              </button>
            </CardMenu>
            <button
              type="button"
              class="persona-note__tool focus-ring"
              aria-label={`Open the full note from ${note.author}`}
              aria-haspopup="dialog"
              title="Open the full note"
              onClick$={() => {
                openFullThread({ kind: "note", id: note.id });
                onClose$();
              }}
            >
              <ExpandIcon />
            </button>
            <button
              type="button"
              onClick$={onClose$}
              class="persona-note__tool focus-ring"
              aria-label="Close note"
              title="Close"
            >
              <CloseIcon />
            </button>
          </div>
        </div>

        <div class="persona-note__scroll">
          <GroundedNote
            data-speech-id={`note-popover-${note.id}`}
            class="comment-markdown persona-note__text"
            onClick$={(event: Event) => revealQuoteFromEvent(event)}
            text={note.note}
          />
          <NoteEvidenceList evidence={note.evidence} context={note.note} />

          {note.thread.map((reply) =>
            reply.authorKind === "user" ? (
              <WriterThreadReply key={reply.id} text={reply.text} />
            ) : (
              <PersonaThreadReply
                key={reply.id}
                personaId={reply.personaId}
                author={reply.author}
                noteAuthor={note.author}
                text={reply.text}
                fresh={
                  reply.id === lastId && now - reply.timestamp < FRESH_REPLY_MS
                }
              />
            ),
          )}

          {streaming && (
            <div
              class="persona-note__reply is-streaming"
              data-author-kind="persona"
            >
              <GroundedNote
                class="comment-markdown"
                onClick$={(event: Event) => revealQuoteFromEvent(event)}
                text={note.streamingReply}
              />
            </div>
          )}
          {note.replying && !streaming && (
            <div class="py-3">
              <EditorialActivity label={`${note.author} is replying`} />
            </div>
          )}
          {note.error && (
            <CardNotice
              tone="error"
              message={note.error}
              actionLabel={note.draft.trim() ? "Send again" : undefined}
              onAction$={() => onReply$(note.id, note.draft, note.author)}
              onDismiss$={
                onDismissError$ ? () => onDismissError$(note.id) : undefined
              }
            />
          )}
          {speechError.value && (
            <CardNotice
              tone="warning"
              icon="voice"
              message="Couldn’t read this aloud."
              detail={speechError.value}
              actionLabel="Voice settings"
              actionHref="/settings/"
              onDismiss$={() => stopSpeech()}
            />
          )}
        </div>
      </section>

      <form
        class="persona-note__compose"
        preventdefault:submit
        onSubmit$={() => onReply$(note.id, note.draft, note.author)}
      >
        <textarea
          value={note.draft}
          data-thread-draft-kind="note"
          data-thread-draft-id={note.id}
          onKeyDown$={[
            holdEnter,
            $((event: KeyboardEvent) => {
              if (event.key !== "Enter" || event.shiftKey || event.isComposing)
                return;
              if (!note.draft.trim() || note.replying) return;
              onReply$(note.id, note.draft, note.author);
            }),
          ]}
          placeholder="Write back…"
          aria-label={`Reply to ${note.author}`}
          class="persona-note__input"
          rows={1}
        />
        <button
          type="submit"
          class="persona-note__send focus-ring"
          disabled={!note.draft.trim() || note.replying}
          aria-label="Reply"
          title="Reply (Enter)"
        >
          <SendIcon />
        </button>
      </form>
    </div>
  );
});

const WriterThreadReply = component$<{ text: string }>(({ text }) => (
  <div
    class="persona-note__reply persona-note__reply--writer comment-markdown"
    data-author-kind="user"
    dangerouslySetInnerHTML={renderMarkdown(text)}
  />
));

/** Full width under the note; a face only when another persona joins in. */
const PersonaThreadReply = component$<{
  personaId?: string;
  author: string;
  noteAuthor: string;
  text: string;
  fresh: boolean;
}>(({ personaId, author, noteAuthor, text, fresh }) => (
  <div
    class={["persona-note__reply", { "is-fresh": fresh }]}
    data-author-kind="persona"
  >
    {author !== noteAuthor && (
      <span class="persona-note__guest" title={author}>
        <PersonaPortrait personaId={personaId} name={author} size={22} />
      </span>
    )}
    <GroundedNote
      class="comment-markdown"
      onClick$={(event: Event) => revealQuoteFromEvent(event)}
      text={text}
    />
  </div>
));
import {
  component$,
  Slot,
  useSignal,
  useVisibleTask$,
  type PropFunction,
  type Signal,
} from "@qwik.dev/core";
import { PersonaPortrait } from "../personas/persona-portrait";
import { resolvePersonaPortrait } from "../../utils/persona-portrait";
import { speechState } from "../../utils/speech";
import { PERSONAS } from "../../utils/personas";

/** Open a margin card's full thread on the board, where it has room. */
export const OPEN_FULL_THREAD_EVENT = "twyne:open-full-thread";
export interface OpenFullThreadDetail {
  kind: "note" | "comment";
  id: string;
}
let pending: OpenFullThreadDetail | null = null;
export function openFullThread(detail: OpenFullThreadDetail) {
  // A board panel that was hidden has not mounted its listener yet; it
  // takes the request from here when it first runs.
  pending = detail;
  window.dispatchEvent(
    new CustomEvent<OpenFullThreadDetail>(OPEN_FULL_THREAD_EVENT, { detail }),
  );
}
/**
 * The request a panel of this kind should act on. It is consumed only once
 * `ready` finds the thread, so a panel still loading can try again.
 */
export function takeFullThread(
  kind: OpenFullThreadDetail["kind"],
  detail: OpenFullThreadDetail | undefined,
  ready: (id: string) => boolean,
): OpenFullThreadDetail | null {
  const request = detail ?? pending;
  if (request?.kind !== kind || !ready(request.id)) return null;
  if (pending?.id === request.id) pending = null;
  return request;
}

/*
 * Shared parts of the cards that open beside a marked passage: persona
 * notes, proposed edits and the writer's own margin notes. One bust, one
 * tool row, one menu and one notice, so the three read as a family.
 */

/**
 * The speaker standing on the card's first box. A cast engraving stands as a
 * figure; anyone without one (a custom persona, the writer) gets a face.
 *
 * The card itself never names its speaker. Hovering or focusing the bust
 * lifts a second layer: who they are, what they read for, and the line of
 * method that explains the note.
 */
export const CardBust = component$<{
  name: string;
  personaId?: string;
  imageUrl?: string;
  color?: string;
  speaking?: "tts" | "live";
  activity?: "writing" | "thinking";
  /** Replaces the cast role, e.g. for the writer's own notes. */
  role?: string;
  /** Replaces the cast focus line. */
  detail?: string;
}>((props) => {
  const identity = resolvePersonaPortrait({
    personaId: props.personaId,
    name: props.name,
  });
  const figure = !!identity.portraitId;
  const cast = PERSONAS.find((p) =>
    props.personaId ? p.id === props.personaId : p.name === props.name,
  );
  const role = props.role ?? cast?.role;
  const detail = props.detail ?? cast?.focus;
  const id = `bust-${(props.personaId ?? props.name).replace(/\W+/g, "-")}`;
  return (
    <span
      class={["persona-note__bust", { "is-face": !figure }]}
      tabIndex={0}
      role="img"
      aria-label={role ? `${identity.name}, ${role}` : identity.name}
      aria-describedby={detail ? id : undefined}
    >
      <span class="persona-note__bust-frame">
        <PersonaPortrait
          personaId={props.personaId}
          name={props.name}
          imageUrl={props.imageUrl}
          color={props.color}
          framing={figure ? "figure" : "face"}
          size={figure ? 96 : 40}
          speaking={props.speaking}
          activity={props.activity}
        />
      </span>
      <span class="persona-note__who" id={id} aria-hidden="true">
        <span class="persona-note__who-name">{identity.name}</span>
        {role && <span class="persona-note__who-role">{role}</span>}
        {detail && <span class="persona-note__who-detail">{detail}</span>}
      </span>
    </span>
  );
});

/**
 * A speaker's face where there is no room for them to stand, such as a
 * board card. The same hover layer as the bust names them.
 */
export const SpeakerFace = component$<{
  name: string;
  personaId?: string;
  imageUrl?: string;
  color?: string;
  size?: number;
  speaking?: "tts" | "live";
}>((props) => {
  const identity = resolvePersonaPortrait({
    personaId: props.personaId,
    name: props.name,
  });
  const cast = PERSONAS.find((p) =>
    props.personaId ? p.id === props.personaId : p.name === props.name,
  );
  return (
    <span
      class="speaker-face"
      tabIndex={0}
      role="img"
      aria-label={cast ? `${identity.name}, ${cast.role}` : identity.name}
    >
      <PersonaPortrait
        personaId={props.personaId}
        name={props.name}
        imageUrl={props.imageUrl}
        color={props.color}
        size={props.size ?? 36}
        speaking={props.speaking}
      />
      <span class="persona-note__who persona-note__who--below" aria-hidden="true">
        <span class="persona-note__who-name">{identity.name}</span>
        {cast?.role && (
          <span class="persona-note__who-role">{cast.role}</span>
        )}
        {cast?.focus && (
          <span class="persona-note__who-detail">{cast.focus}</span>
        )}
      </span>
    </span>
  );
});

/** A ⋯ button whose menu closes on Escape, on choice and on leaving it. */
export const CardMenu = component$<{ label?: string }>((props) => {
  const open = useSignal(false);
  return (
    <span
      class="persona-note__menu"
      onFocusOut$={(event, el) => {
        const next = (event as FocusEvent).relatedTarget as Node | null;
        if (!next || !el.contains(next)) open.value = false;
      }}
      onKeyDown$={(event) => {
        if ((event as KeyboardEvent).key === "Escape") open.value = false;
      }}
    >
      <button
        type="button"
        class="persona-note__tool focus-ring"
        aria-label={props.label ?? "More actions"}
        title={props.label ?? "More actions"}
        aria-haspopup="menu"
        aria-expanded={open.value}
        onClick$={() => (open.value = !open.value)}
      >
        <MoreIcon />
      </button>
      {open.value && (
        <span
          class="persona-note__menu-list"
          role="menu"
          onClick$={() => (open.value = false)}
        >
          <Slot />
        </span>
      )}
    </span>
  );
});

/** Why the passage with this speech id would not read aloud, if it would not. */
export function useSpeechError(id: Signal<string>): Signal<string> {
  const error = useSignal("");
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ track, cleanup }) => {
    const current = track(id);
    const sync = () => {
      const s = speechState();
      error.value =
        s.id === current && s.status === "error"
          ? s.error?.message || "This could not be read aloud."
          : "";
    };
    sync();
    window.addEventListener("twyne:speech", sync);
    cleanup(() => window.removeEventListener("twyne:speech", sync));
  });
  return error;
}

/**
 * One compact line inside the card: a tinted glyph, the message, and at most
 * one way forward. The card's own colour stays for the persona; tone colours
 * only the glyph and a hairline, so a warning never outshouts the note.
 */
export const CardNotice = component$<{
  tone: "error" | "warning";
  icon?: "alert" | "voice";
  message: string;
  /** The longer reason, on hover; the line itself stays short. */
  detail?: string;
  actionLabel?: string;
  actionHref?: string;
  onAction$?: PropFunction<() => void>;
  onDismiss$?: PropFunction<() => void>;
}>((props) => (
  <div
    class="persona-note__notice"
    data-tone={props.tone}
    role={props.tone === "error" ? "alert" : "status"}
  >
    <span class="persona-note__notice-icon" aria-hidden="true">
      {props.icon === "voice" ? <MutedIcon /> : <AlertIcon />}
    </span>
    <p class="persona-note__notice-text" title={props.detail}>
      {props.message}{" "}
      {props.actionLabel && props.actionHref && (
        <a
          href={props.actionHref}
          class="persona-note__notice-action focus-ring"
        >
          {props.actionLabel}
        </a>
      )}
    </p>
    {props.actionLabel && !props.actionHref && props.onAction$ && (
      <button
        type="button"
        class="persona-note__notice-retry focus-ring"
        aria-label={props.actionLabel}
        title={props.actionLabel}
        onClick$={props.onAction$}
      >
        <RetryIcon />
      </button>
    )}
    {props.onDismiss$ && (
      <button
        type="button"
        class="persona-note__notice-dismiss focus-ring"
        aria-label="Dismiss"
        title="Dismiss"
        onClick$={props.onDismiss$}
      >
        <CloseIcon />
      </button>
    )}
  </div>
));

