.persona-note__bust {
  --pp-figure-width: 8.5rem;
  position: absolute;
  z-index: 2;
  bottom: 0;
  left: 0.4rem;
  width: 4.5rem;
  height: calc(2.5rem + var(--persona-note-rise) + 1.5px);
  border-radius: 6px;
  outline: 0;
  cursor: help;
}
.persona-note__bust-frame {
  position: absolute;
  inset: 0;
  overflow: hidden;
  -webkit-mask-image:
    linear-gradient(to bottom, #000 68%, transparent 100%),
    linear-gradient(to right, transparent, #000 16%, #000 84%, transparent);
  -webkit-mask-composite: source-in;
  mask-image:
    linear-gradient(to bottom, #000 68%, transparent 100%),
    linear-gradient(to right, transparent, #000 16%, #000 84%, transparent);
  mask-composite: intersect;
}
.persona-note__bust .persona-portrait[data-framing="figure"] {
  position: absolute;
  top: calc(56% - var(--pp-figure-width) * 1.25 * var(--fy, 0.3));
  left: calc(50% - var(--pp-figure-width) * var(--fx, 0.5));
  transition:
    transform 0.28s cubic-bezier(0.22, 1, 0.36, 1),
    filter 0.28s ease;
  transform-origin: 50% 80%;
}
.persona-note__bust.is-face .persona-note__bust-frame {
  overflow: visible;
  -webkit-mask-image: none;
  mask-image: none;
}
.persona-note__bust .persona-portrait[data-framing="face"] {
  position: absolute;
  bottom: 0.25rem;
  left: 0.5rem;
  transition: transform 0.22s cubic-bezier(0.22, 1, 0.36, 1);
}
/* Hover lifts the speaker a little toward the reader. */
.persona-note__bust:hover .persona-portrait[data-framing="figure"],
.persona-note__bust:focus-visible .persona-portrait[data-framing="figure"] {
  transform: translateY(-3px) scale(1.04);
  filter: drop-shadow(0 6px 8px rgb(32 25 16 / 0.18));
}
.persona-note__bust:hover .persona-portrait[data-framing="face"],
.persona-note__bust:focus-visible .persona-portrait[data-framing="face"] {
  transform: scale(1.08);
}
.persona-note__bust:focus-visible .persona-note__bust-frame {
  border-radius: 6px;
  box-shadow: 0 0 0 2px var(--comment-color);
}

/* Card controls: every one says it is pressable (cursor, tint, ink) and
   answers a press. Each also has its own small gesture on hover. */
.twyne-card button:not(:disabled),
.twyne-card a[href] {
  cursor: pointer;
}
.twyne-card button:disabled {
  cursor: not-allowed;

/* A face that names its speaker on hover, where there is no room to stand. */
.speaker-face {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  border-radius: 9999px;
  outline: 0;
  cursor: help;
}
.speaker-face > .persona-portrait {
  transition: transform 0.22s cubic-bezier(0.22, 1, 0.36, 1);
}
.speaker-face:hover > .persona-portrait,
.speaker-face:focus-visible > .persona-portrait {
  transform: scale(1.08);
}
.speaker-face:focus-visible {
  box-shadow: 0 0 0 2px var(--comment-color, var(--color-ink));
}
.speaker-face:hover .persona-note__who,
.speaker-face:focus-visible .persona-note__who {
  opacity: 1;
  transform: none;
  transition-delay: 0.18s;
}
.persona-note__who.persona-note__who--below {
  top: calc(100% + 0.4rem);
  bottom: auto;
  z-index: 20;
  transform: translateY(-4px) scale(0.98);
  transform-origin: 1rem 0;
}

/* The second layer: who is speaking and what they read for. */
.persona-note__who {
  position: absolute;
  z-index: 3;
  bottom: calc(100% - var(--persona-note-rise) + 0.5rem);
  left: 0;
  display: flex;
  width: max-content;
  max-width: 15rem;
  flex-direction: column;
  gap: 0.15rem;
  padding: 0.55rem 0.75rem 0.6rem;
  border: 1px solid color-mix(in srgb, var(--comment-color) 45%, transparent);
  border-left: 3px solid var(--comment-color);
  border-radius: 6px;
  background: var(--color-paper);
  box-shadow: 0 14px 26px -14px rgb(32 25 16 / 0.5);
  opacity: 0;
  pointer-events: none;
  transform: translateY(4px) scale(0.98);
  transform-origin: 1rem 100%;
  transition:
    opacity 0.16s ease,
    transform 0.2s cubic-bezier(0.22, 1, 0.36, 1);
  transition-delay: 0s;
}
.persona-note__bust:hover .persona-note__who,
.persona-note__bust:focus-visible .persona-note__who {
  opacity: 1;
  transform: none;
  transition-delay: 0.18s;
}
.persona-note__who-name {
  color: var(--color-ink);
  font: 600 0.9375rem/1.25 var(--font-display, var(--font-serif));
}
.persona-note__who-role {
  color: var(--comment-color);
  font: 0.625rem/1.3 var(--font-typewriter);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.persona-note__who-detail {
  margin-top: 0.15rem;
  color: var(--color-ink-light);
  font: italic 0.8125rem/1.4 var(--font-serif);
}

.persona-note__tools {
  display: flex;
  align-items: center;
  gap: 0.125rem;

