// Build a persona-note popover in the manuscript's outside margin.
// Position is computed by the same pure geometry used for writer
// comments, so both authors share one interaction grammar. Splitting attribute
// read from geometry lets us re-use the same attribute
// extractor when opening from the mark-anchor chip (where the
// chip's own rect is the anchor, not the marked text's rect).
const buildNotePopoverFromRect = (
  rect: DOMRect,
  attrs: {
    id: string;
    author: string;
    color: string;
    label: string;
    note: string;
    quote?: string;
    briefTitle?: string;
  },
  pinned: boolean,
): NotePopover => {
  const pageRect = el
    .closest<HTMLElement>(".page-canvas")
    ?.getBoundingClientRect();
  const geom = computeMarginCardGeometry({
    vw: window.innerWidth,
    vh: window.innerHeight,
    rect: {
      left: rect.left,
      top: rect.top,
      bottom: rect.bottom,
    },
    page: pageRect
      ? { left: pageRect.left, right: pageRect.right }
      : { left: rect.left, right: rect.right },
  });
  return {
    id: attrs.id,
    author: attrs.author,
    color: attrs.color,
    label: attrs.label,
    note: attrs.note,
    quote: attrs.quote,
    briefTitle: attrs.briefTitle,
    draft: threadDrafts[noteItemId(attrs.id)] ?? "",
    dismissed: false,
    pinned,
    x: geom.x,
    top: geom.top,
    bottom: geom.bottom,
    maxH: geom.maxH,
    placement: geom.placement,
    thread: [],
    replying: false,
    streamingReply: "",
    error: null,
  };
};

const readPersonaNoteAttrs = (noteSpan: HTMLElement) => ({
  id: noteSpan.getAttribute("data-persona-note-id") ?? "",
  author: noteSpan.getAttribute("data-persona-note-author") ?? "",
  color:
    noteSpan.getAttribute("data-persona-note-color") ??
    "var(--color-vermilion)",
  label: noteSpan.getAttribute("data-persona-note-label") ?? "",
  note: noteSpan.getAttribute("data-persona-note-note") ?? "",
  quote: noteSpan.getAttribute("data-persona-note-quote") ?? undefined,
  briefTitle:
    noteSpan.getAttribute("data-persona-note-brief") ?? undefined,
});

const buildNotePopover = (
  noteSpan: HTMLElement,
  pinned: boolean,
): NotePopover =>
  buildNotePopoverFromRect(
    noteSpan.getBoundingClientRect(),
    readPersonaNoteAttrs(noteSpan),
    pinned,
  );
// When a new popover is born, ask the personas panel for any
// existing reply thread for this note so the popover can
// render the conversation inline. The panel mirrors it back
// via `twyne:persona-reply-thread`.
const requestThreadFor = (noteId: string) => {
  if (!noteId) return;
  window.dispatchEvent(
    new CustomEvent("twyne:request-persona-thread", {
      detail: { noteId },
    }),
  );
};
const buildAndPin = (noteSpan: HTMLElement, pinned: boolean) => {
  const pop = buildNotePopover(noteSpan, pinned);
  store.notePopover = pop;
  requestThreadFor(pop.id);
};

// Open a persona note's conversation. While the flow surface is
// carrying the margin, the note already has a card there, so the
// conversation unfolds in that card's slot rather than floating in
// a second place.
const openNoteThread = async (
  noteSpan: HTMLElement,
  anchorRect: DOMRect,
) => {
  const token = ++threadRequest.value;
  const attrs = readPersonaNoteAttrs(noteSpan);
  const itemId = noteItemId(attrs.id);
  const slot = await marginSurface()?.reveal(
    itemId,
    noteSpan.getBoundingClientRect().top,
  );
  if (token !== threadRequest.value || !noteSpan.isConnected) return;
  const pop = buildNotePopoverFromRect(anchorRect, attrs, true);
  // One conversation at a time — but never throw away a reply the
  // writer has started.
  store.userCommentPopover = null;
  store.suggestionPopover = null;
  store.selectionAction = null;
  store.notePopover = slot
    ? {
        ...pop,
        ...slotPlacement(slot),
        placement: "below",
        margin: itemId,
      }
    : pop;
  requestThreadFor(pop.id);
};

// Open the suggestion card from any source (click on the
// marked text, click on its mark-anchor chip). The chip's own
// rect is usually a better anchor than the marked text's (it
// sits at the end of the run and is unambiguous), so we accept
// an explicit `anchorEl` when one is available.
const openSuggestionPopover = (
  suggestionSpan: HTMLElement,
  anchorEl?: HTMLElement,
) => {
  const token = ++threadRequest.value;
  const target = anchorEl ?? suggestionSpan;
  const rect = target.getBoundingClientRect();
  const pageRect = el
    .closest<HTMLElement>(".page-canvas")
    ?.getBoundingClientRect();
  // A proposed rewrite is read beside its passage, like any note —
  // never over a dimmed page.
  const geom = computeMarginCardGeometry({
    vw: window.innerWidth,
    vh: window.innerHeight,
    rect: { left: rect.left, top: rect.top, bottom: rect.bottom },
    page: pageRect
      ? { left: pageRect.left, right: pageRect.right }
      : { left: rect.left, right: rect.right },
  });
  const id = suggestionSpan.getAttribute("data-suggestion-id") ?? "";
  store.notePopover = null;
  store.userCommentPopover = null;
  store.selectionAction = null;
  store.suggestionPopover = {
    id,
    versionId:
      suggestionSpan.getAttribute("data-suggestion-versionId") ?? "",
    author: suggestionSpan.getAttribute("data-suggestion-author") ?? "",
    color:
      suggestionSpan.getAttribute("data-suggestion-color") ??
      "var(--color-vermilion)",
    original: suggestionSpan.textContent ?? "",
    replacement:
      suggestionSpan.getAttribute("data-suggestion-replacement") ?? "",
    rationale:
      suggestionSpan.getAttribute("data-suggestion-rationale") ?? "",
    x: geom.x,
    top: geom.top,
    bottom: geom.bottom,
    maxH: geom.maxH,
    busy: false,
  };
  const itemId = suggestionItemId(id);
  void marginSurface()
    ?.reveal(itemId, suggestionSpan.getBoundingClientRect().top)
    .then((slot) => {
      if (
        !slot ||
        token !== threadRequest.value ||
        store.suggestionPopover?.id !== id
      )
        return;
      store.suggestionPopover = {
        ...store.suggestionPopover,
        ...slotPlacement(slot),
        margin: itemId,
      };
    });
};

// ── Hover: preview a persona note below its sentence ──
// Non-blocking rules:
//   1. Hover-intent delay (350ms) — passing through doesn't
//      accidentally open a card.
//   2. Typing disarm — once the writer types (or deletes /
//      hits Enter), the next hover is suppressed. We re-arm
//      only on real mouse motion (>3px), filtering the
//      synthetic mousemove that scroll-under-cursor fires.
//   3. Pinned / replying / has-thread cards never close from
//      mouseout alone.
// `openUserCommentPopover` is declared further down the component,
// after this task, so the optimizer cannot hand it to this closure.
// Ask for it by event; the task beside its declaration answers.
const openWriterComment = (commentId: string, markEl: HTMLElement) =>
  window.dispatchEvent(
    new CustomEvent<OpenWriterCommentDetail>(
      OPEN_WRITER_COMMENT_EVENT,
      {
        detail: { commentId, markEl },
      },
    ),
  );
let hoverTimer: ReturnType<typeof setTimeout> | null = null;
let hoverArmed = true;
let hoveredWriterCommentId: string | null = null;
let lastMouse = { x: 0, y: 0 };
const clearHoverTimer = () => {
  if (hoverTimer) {
    clearTimeout(hoverTimer);
    hoverTimer = null;
  }
};
el.addEventListener("mouseover", (e) => {
  if (store.zenMode) {
    clearHoverTimer();
    return;
  }
  const target = e.target as HTMLElement;
  const noteSpan = target.closest(
    ".twyne-persona-note",
  ) as HTMLElement | null;
  const writerCommentSpan = target.closest(
    '.twyne-comment-mark:not([data-comment-resolved="true"])',
  ) as HTMLElement | null;
  const chip = target.closest(
    ".twyne-mark-anchor",
  ) as HTMLElement | null;
  if (!noteSpan && !writerCommentSpan && !chip) return;
  // With the margin carrying notes, pointing at a passage peeks its
  // card there (the flow surface draws the connection); the floating
  // preview would be a second copy of the same note.
  if (marginSurface()) {
    clearHoverTimer();
    return;
  }
  if (writerCommentSpan) {
    if (store.userCommentPopover?.visible) return;
    if (!hoverArmed) return;
    const commentId =
      writerCommentSpan.getAttribute("data-comment-id") ?? "";
    if (!commentId) return;
    clearHoverTimer();
    hoverTimer = setTimeout(() => {
      if (store.zenMode) return;
      hoveredWriterCommentId = commentId;
      openWriterComment(commentId, writerCommentSpan);
    }, 350);
    return;
  }
  // Don't clobber a pinned card the writer is interacting with.
  if (store.notePopover?.pinned) return;
  if (!hoverArmed) return;
  // Resolve to the actual note span for geometry. The chip
  // belongs to whichever note span it sits in (or directly
  // adjacent to).
  const anchor =
    noteSpan ??
    (chip?.closest(".twyne-persona-note") as HTMLElement | null);
  if (!anchor) return;
  clearHoverTimer();
  hoverTimer = setTimeout(() => {
    if (store.zenMode) return;
    buildAndPin(anchor, false);
  }, 350);
});
el.addEventListener("mouseout", (e) => {
  const related = (e as MouseEvent).relatedTarget as HTMLElement | null;
  // Stay open while moving onto the card, the marked span, or
  // its corresponding anchor chip (text → chip → card).
  if (related?.closest(".manuscript-comment-card")) return;
  if (related?.closest(".twyne-persona-note")) return;
  if (related?.closest(".twyne-comment-mark")) return;
  if (related?.closest(".twyne-mark-anchor")) return;
  // Even when we don't close, cancel any pending hover-open
  // timer so a fast pass-through doesn't surprise the writer.
  clearHoverTimer();
  if (hoveredWriterCommentId) {
    if (
      store.userCommentPopover?.id === hoveredWriterCommentId &&
      !store.userCommentPopover.draft.trim()
    ) {
      store.userCommentPopover = null;
    }
    hoveredWriterCommentId = null;
    return;
  }
  // Mid-conversation: keep the live thread open even if the
  // popover was opened by hover rather than a click.
  if (store.notePopover?.pinned) return;
  if (store.notePopover?.replying) return;
  if ((store.notePopover?.thread.length ?? 0) > 0) return;
  store.notePopover = null;
});

// ── Click handler: anchor-chip routes by data-anchor-kind; mark
// clicks fall through to ProseMirror (caret placement, no popover). ──
el.addEventListener("click", (e) => {
  dismissEditorialFurniture();
  const target = e.target as HTMLElement;

  // Anchor chip first — must preventDefault so clicking the
  // chip doesn't also place the caret.
  const chip = target.closest(
    ".twyne-mark-anchor",
  ) as HTMLElement | null;
  if (chip) {
    e.preventDefault();
    const kind = chip.getAttribute("data-anchor-kind");
    const id = chip.getAttribute("data-anchor-id") ?? "";
    if (!id) return;
    const chipRect = chip.getBoundingClientRect();
    if (kind === "comment") {
      hoveredWriterCommentId = null;
      const span = el.querySelector(
        `.twyne-comment-mark[data-comment-id="${CSS.escape(id)}"]`,
      ) as HTMLElement | null;
      if (span) openWriterComment(id, span);
    } else if (kind === "suggestion") {
      const span = el.querySelector(
        `.twyne-suggestion[data-suggestion-id="${CSS.escape(id)}"]`,
      ) as HTMLElement | null;
      if (span) openSuggestionPopover(span, chip);
    } else if (kind === "note") {
      const span = el.querySelector(
        `.twyne-persona-note[data-persona-note-id="${CSS.escape(id)}"]`,
      ) as HTMLElement | null;
      if (span) void openNoteThread(span, chipRect);
    }
    return;
  }

  // Plain click on a marked span — defer to ProseMirror for
  // caret placement. Only act to close stray cards (click-away).
  if (!target.closest(".persona-note-card")) {
    const inNote = !!target.closest(".twyne-persona-note");
    if (!inNote) store.notePopover = null;
  }
  if (
    !target.closest(".twyne-suggestion") &&
    !target.closest(".suggestion-card")
  ) {
    store.suggestionPopover = null;
  }
  if (
    !target.closest(".twyne-comment-mark") &&
    !target.closest(".user-comment-card")
  ) {
    store.userCommentPopover = null;
  }
});

// ── Double-click on a comment mark: dismiss the popover and drop
// the caret into the marked passage. Now a safety net since the
// single-click path no longer opens the popover for marked text. ──
el.addEventListener("dblclick", (e) => {
  const target = e.target as HTMLElement;
  const commentMark = target.closest(
    ".twyne-comment-mark",
  ) as HTMLElement | null;
  if (!commentMark) return;
  store.userCommentPopover = null;
  const pos = editor.view.posAtDOM(commentMark, 0);
  if (typeof pos === "number" && pos >= 0) {
    editor.commands.focus(pos);
  } else {
    editor.commands.focus();
  }
});

// ── Typing suppression: disarm hover, close no-thread previews ──
// We listen on the editor element rather than
// `editor.on("transaction")` so that remote multiplayer
// transactions don't disarm hover based on *someone else's*
// keystrokes.
el.addEventListener("keydown", (e) => {
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  const k = e.key;
  const isPrintable = k.length === 1;
  if (
    !isPrintable &&
    k !== "Backspace" &&
    k !== "Delete" &&
    k !== "Enter"
  ) {
    return;
  }
  hoverArmed = false;
  clearHoverTimer();
  // An unpinned preview (no thread, not replying) closes — but a
  // pinned card or one that's mid-thread stays open so the
  // conversation can continue.
  const p = store.notePopover;
  if (p && !p.pinned && !p.replying && p.thread.length === 0) {
    store.notePopover = null;
  }
});
// Re-arm hover only on real mouse motion (not synthetic scroll
// mousemove events). Listener on `document` so moving out of the
// editor area still re-arms.
const rearmOnMove = (e: MouseEvent) => {
  const dx = e.clientX - lastMouse.x;
  const dy = e.clientY - lastMouse.y;
  lastMouse = { x: e.clientX, y: e.clientY };
  if (Math.hypot(dx, dy) > 3) {
    hoverArmed = true;
  }
};
document.addEventListener("mousemove", rearmOnMove);

// ── Global Escape: close any of the three popovers ──
// Listens on `window` so it works even when focus is in the
// reply textarea.
const onGlobalKeydown = (e: KeyboardEvent) => {
  const target = e.target as HTMLElement | null;
  const editingField =
    !!target &&
    (target.matches("input, textarea, select") ||
      (target.isContentEditable && !target.closest(".ProseMirror")));

import { Mark, type Editor } from "@tiptap/core";

export interface PersonaNoteMarkOptions {
  HTMLAttributes: Record<string, any>;
}

export interface PersonaNoteAttributes {
  id: string;
  author: string;
  color: string;
  label: string;
  note: string;
  /** The passage the note is pinned to — rendered as a preview in the popover. */
  quote?: string;
  /** Brief title captured at convene time. */
  briefTitle?: string;
}

declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    personaNote: {
      setPersonaNote: (attrs: PersonaNoteAttributes) => ReturnType;
      unsetPersonaNote: () => ReturnType;
    };
  }
}

/**
 * An editor persona's margin note, pinned to the passage it concerns.
 * Stored as a mark so notes travel with the saved folio HTML.
 */
export const PersonaNoteMark = Mark.create<PersonaNoteMarkOptions>({
  name: "personaNote",

  // Several editors may ground conflicting readings in the exact same quote.
  // ProseMirror otherwise treats a second mark of this type as a replacement
  // for the first, which silently removes the earlier note's manuscript anchor.
  excludes: "",

  addOptions() {
    return {
      HTMLAttributes: {},
    };
  },

  addAttributes() {
    const dataAttr = (name: string, fallback = "") => ({
      default: fallback,
      parseHTML: (element: HTMLElement) =>
        element.getAttribute(`data-persona-note-${name}`) ?? fallback,
      renderHTML: (attributes: Record<string, any>) => {
        if (!attributes[name]) return {};
        return { [`data-persona-note-${name}`]: attributes[name] };
      },
    });

    return {
      id: dataAttr("id"),
      author: dataAttr("author"),
      color: dataAttr("color", "var(--color-vermilion)"),
      label: dataAttr("label"),
      note: dataAttr("note"),
      // quote + briefTitle are read back from the DOM by the
      // popover to render a quote preview and a "filed against"
      // line. They were being silently dropped before because the
      // attribute list didn't declare them — setPersonaNote would
      // pass them in and ProseMirror would discard them.
      quote: dataAttr("quote"),
      // The DOM attribute is `data-persona-note-brief` (legacy
      // name from the popover's getAttribute call) while the
      // mark's API name is `briefTitle`. Wire them by hand.
      // The default is `null` (not `""`) so the renderHTML's
      // "is it set?" check doesn't false-negative on an empty
      // string — `dataAttr`'s `if (!attributes[name])` returns
      // `{}` for `""`, which would silently drop every note's
      // briefTitle from the rendered HTML.
      briefTitle: {
        default: null as string | null,
        parseHTML: (element: HTMLElement) =>
          element.getAttribute("data-persona-note-brief"),
        renderHTML: (attributes: Record<string, any>) => {
          if (attributes.briefTitle == null) return {};
          return { "data-persona-note-brief": attributes.briefTitle };
        },
      },
    };
  },

  parseHTML() {
    return [{ tag: "span[data-persona-note-id]" }];
  },

  renderHTML({ HTMLAttributes }) {
    const color =
      HTMLAttributes["data-persona-note-color"] ?? "var(--color-vermilion)";
    return [
      "span",
      {
        ...this.options.HTMLAttributes,
        ...HTMLAttributes,
        class: "twyne-persona-note",
        style: `--note-color: ${color};`,
      },
      0,
    ];
  },

  addCommands() {
    return {
      setPersonaNote:
        (attrs) =>
        ({ chain }) =>
          chain().setMark("personaNote", attrs).run(),
      unsetPersonaNote:
        () =>
        ({ chain }) =>
          chain().unsetMark("personaNote").run(),
    };
  },
});

/** Remove one persona note without disturbing another note on the same quote. */
export function removePersonaNoteMarkById(
  editor: Editor,
  noteId: string,
): boolean {
  const { state, view } = editor;
  const type = state.schema.marks.personaNote;
  if (!type) return false;

  const transaction = state.tr;
  state.doc.descendants((node, pos) => {
    if (!node.isText) return true;
    for (const mark of node.marks) {
      if (mark.type === type && mark.attrs.id === noteId) {
        transaction.removeMark(pos, pos + node.nodeSize, mark);
      }
    }
    return true;
  });
  if (!transaction.docChanged) return false;
  view.dispatch(transaction);
  return true;
}

import type { Editor, NodeViewRendererProps } from "@tiptap/core";
import type { Node as ProseMirrorNode } from "@tiptap/pm/model";
import type { NodeView } from "@tiptap/pm/view";
import { EndnoteNode } from "./endnote-node";
import {
  adjacentInlineNote,
  collectInlineNotes,
  convertInlineNote,
  deleteInlineNote,
  focusInlineNoteReference,
  normalizeInlineNoteKind,
  updateInlineNote,
  type InlineNoteKind,
} from "../note-editing";

function button(label: string): HTMLButtonElement {
  const element = document.createElement("button");
  element.type = "button";
  element.textContent = label;
  return element;
}

function stylePopover(element: HTMLElement): void {
  Object.assign(element.style, {
    position: "fixed",
    zIndex: "var(--z-dropdown, 40)",
    width: "min(22rem, calc(100vw - 2rem))",
    padding: "0.8rem",
    border: "1px solid var(--color-paper-3, #d2c8b5)",
    borderRadius: "4px",
    background: "var(--color-paper, #fffdf8)",
    color: "var(--color-ink, #221f1a)",
    boxShadow: "0 12px 36px rgb(0 0 0 / 0.18)",
    fontFamily: "var(--font-typewriter, monospace)",
  });
}

function positionPopover(popover: HTMLElement, marker: HTMLElement): void {
  const rect = marker.getBoundingClientRect();
  const width = Math.min(352, Math.max(240, window.innerWidth - 32));
  const height = popover.getBoundingClientRect().height || 260;
  const left = Math.max(
    16,
    Math.min(rect.left, Math.max(16, window.innerWidth - width - 16)),
  );
  const below = rect.bottom + 8;
  const above = rect.top - height - 8;
  const top =
    below + height <= window.innerHeight - 16 ? below : Math.max(16, above);

  popover.style.left = `${left}px`;
  popover.style.top = `${top}px`;
  popover.style.maxHeight = `${Math.max(120, window.innerHeight - 32)}px`;
  popover.style.overflowY = "auto";
}

/**
 * DOM NodeView kept in a new adapter file so the existing endnote node remains
 * untouched. Integration can register InlineNoteNode wherever EndnoteNode is
 * currently registered; its schema and HTML contract are inherited verbatim.
 */
export class InlineNotePopoverView implements NodeView {
  dom: HTMLElement;

  private node: ProseMirrorNode;

  private readonly editor: Editor;

  private readonly getPos: NodeViewRendererProps["getPos"];

  private popover: HTMLElement | null = null;

  private textarea: HTMLTextAreaElement | null = null;

  private outsidePointerDown: ((event: PointerEvent) => void) | null = null;

  private readonly refreshMarker = () => {
    this.renderMarker();
    if (this.popover) {
      this.syncPopover();
      positionPopover(this.popover, this.dom);
    }
  };

  constructor(props: NodeViewRendererProps) {
    this.node = props.node;
    this.editor = props.editor;
    this.getPos = props.getPos;

    this.dom = document.createElement("sup");
    this.dom.className = "twyne-endnote twyne-inline-note-reference";
    this.dom.tabIndex = 0;
    this.dom.setAttribute("contenteditable", "false");
    this.dom.setAttribute("aria-haspopup", "dialog");

    this.dom.addEventListener("click", (event) => {
      event.preventDefault();
      this.open();
    });
    this.dom.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        this.open();
      } else if (event.key === "Escape") {
        event.preventDefault();
        this.returnFocusToReference();
      }
    });

    this.editor.on("transaction", this.refreshMarker);
    this.renderMarker();
  }

  update(node: ProseMirrorNode): boolean {
    if (node.type !== this.node.type) return false;
    this.node = node;
    this.refreshMarker();
    return true;
  }

  stopEvent(event: Event): boolean {
    const target = event.target;
    return (
      target instanceof globalThis.Node &&
      (this.dom.contains(target) || Boolean(this.popover?.contains(target)))
    );
  }

  ignoreMutation(): boolean {
    return true;
  }

  destroy(): void {
    this.editor.off("transaction", this.refreshMarker);
    this.close(false);
  }

  open(): void {
    if (this.popover) {
      this.textarea?.focus();
      return;
    }

    const note = this.currentNote();
    if (!note) return;

    const popover = document.createElement("div");
    popover.className = "twyne-inline-note-popover";
    popover.dataset.inlineNotePopover = "true";
    popover.setAttribute("role", "dialog");
    popover.setAttribute("aria-modal", "false");
    stylePopover(popover);

    const heading = document.createElement("div");
    heading.dataset.noteHeading = "true";
    Object.assign(heading.style, {
      marginBottom: "0.55rem",
      fontSize: "0.72rem",
      fontWeight: "700",
      letterSpacing: "0.08em",
      textTransform: "uppercase",
    });

    const textarea = document.createElement("textarea");
    textarea.value = note.text;
    textarea.rows = 5;
    textarea.setAttribute("aria-label", "Note text");
    Object.assign(textarea.style, {
      display: "block",
      width: "100%",
      boxSizing: "border-box",
      resize: "vertical",
      padding: "0.55rem",
      border: "1px solid var(--color-paper-3, #d2c8b5)",
      borderRadius: "3px",
      background: "var(--color-paper-soft, #faf6ed)",
      color: "inherit",
      font: "inherit",
      lineHeight: "1.45",
    });
    textarea.addEventListener("input", () => {
      updateInlineNote(this.editor, this.getPos, { text: textarea.value });
    });
    textarea.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        this.returnFocusToReference();
      }
    });

    const kindLabel = document.createElement("label");
    kindLabel.textContent = "Kind ";
    Object.assign(kindLabel.style, {
      display: "inline-flex",
      alignItems: "center",
      gap: "0.4rem",
      marginTop: "0.65rem",
      fontSize: "0.75rem",
    });

    const kindSelect = document.createElement("select");
    kindSelect.setAttribute("aria-label", "Note kind");
    for (const [value, label] of [
      ["footnote", "Footnote"],
      ["endnote", "Endnote"],
    ] as const) {
      const option = document.createElement("option");
      option.value = value;
      option.textContent = label;
      kindSelect.append(option);
    }
    kindSelect.value = note.kind;
    kindSelect.addEventListener("change", () => {
      convertInlineNote(
        this.editor,
        this.getPos,
        normalizeInlineNoteKind(kindSelect.value),
      );
    });
    kindLabel.append(kindSelect);

    const actions = document.createElement("div");
    Object.assign(actions.style, {
      display: "flex",
      flexWrap: "wrap",
      gap: "0.35rem",
      marginTop: "0.75rem",
    });

    const previous = button("Previous");
    previous.dataset.notePrevious = "true";
    previous.addEventListener("click", () => this.openAdjacent("previous"));

    const reference = button("Reference");
    reference.dataset.noteReference = "true";
    reference.addEventListener("click", () => this.returnFocusToReference());

    const next = button("Next");
    next.dataset.noteNext = "true";
    next.addEventListener("click", () => this.openAdjacent("next"));

    const remove = button("Delete");
    remove.dataset.noteDelete = "true";
    remove.setAttribute("aria-label", "Delete note");
    remove.addEventListener("click", () => {
      this.close(false);
      deleteInlineNote(this.editor, this.getPos);
      this.editor.view.focus();
    });

    for (const action of [previous, reference, next, remove]) {
      Object.assign(action.style, {
        padding: "0.35rem 0.5rem",
        border: "1px solid var(--color-paper-3, #d2c8b5)",
        borderRadius: "3px",
        background: "var(--color-paper-soft, #faf6ed)",
        color: "inherit",
        cursor: "pointer",
        font: "inherit",
        fontSize: "0.72rem",
      });
      actions.append(action);
    }

    popover.append(heading, textarea, kindLabel, actions);
    document.body.append(popover);
    this.popover = popover;
    this.textarea = textarea;
    this.syncPopover();
    positionPopover(popover, this.dom);

    this.outsidePointerDown = (event) => {
      const target = event.target;
      if (!(target instanceof globalThis.Node)) return;
      if (this.dom.contains(target) || popover.contains(target)) return;
      this.close(false);
    };
    document.addEventListener("pointerdown", this.outsidePointerDown, true);

    requestAnimationFrame(() => {
      this.textarea?.focus();
      this.textarea?.setSelectionRange(
        this.textarea.value.length,
        this.textarea.value.length,
      );
    });
  }

  close(returnFocus = false): void {
    if (this.outsidePointerDown) {
      document.removeEventListener(
        "pointerdown",
        this.outsidePointerDown,
        true,
      );
      this.outsidePointerDown = null;
    }
    this.popover?.remove();
    this.popover = null;
    this.textarea = null;

    if (returnFocus) {
      focusInlineNoteReference(this.editor, this.getPos);
      this.dom.focus();
    }
  }

  private currentNote() {
    const pos = this.getPos();
    if (typeof pos !== "number") return null;
    return (
      collectInlineNotes(this.editor.state.doc).find(
        (note) => note.pos === pos,
      ) ?? null
    );
  }

  private renderMarker(): void {
    const note = this.currentNote();
    if (!note) return;

    const kind = normalizeInlineNoteKind(note.kind);
    this.dom.dataset.type = kind;
    this.dom.dataset.inlineNoteNumber = String(note.number);
    this.dom.setAttribute("data-endnote-text", note.text);
    this.dom.title = note.text;
    this.dom.setAttribute(
      "aria-label",
      `${kind === "footnote" ? "Footnote" : "Endnote"} ${note.number}: ${
        note.text || "Empty note"
      }. Activate to edit.`,
    );
  }

  private syncPopover(): void {
    const note = this.currentNote();
    if (!note || !this.popover) return;

    const heading = this.popover.querySelector<HTMLElement>(
      "[data-note-heading]",
    );
    const select = this.popover.querySelector<HTMLSelectElement>(
      'select[aria-label="Note kind"]',
    );
    const previous = this.popover.querySelector<HTMLButtonElement>(
      "[data-note-previous]",
    );
    const next =
      this.popover.querySelector<HTMLButtonElement>("[data-note-next]");

    if (heading) {
      heading.textContent = `${
        note.kind === "footnote" ? "Footnote" : "Endnote"
      } ${note.number}`;
    }
    if (select && select.value !== note.kind) select.value = note.kind;
    if (this.textarea && document.activeElement !== this.textarea) {
      this.textarea.value = note.text;
    }

    if (previous) {
      previous.disabled = !adjacentInlineNote(
        this.editor.state.doc,
        this.getPos,
        "previous",
      );
    }
    if (next) {
      next.disabled = !adjacentInlineNote(
        this.editor.state.doc,
        this.getPos,
        "next",
      );
    }
  }

  private returnFocusToReference(): void {
    this.close(true);
  }

  private openAdjacent(direction: "previous" | "next"): void {
    const adjacent = adjacentInlineNote(
      this.editor.state.doc,
      this.getPos,
      direction,
    );
    if (!adjacent) return;

    this.close(false);
    focusInlineNoteReference(this.editor, adjacent.pos);
    const target = this.editor.view.nodeDOM(adjacent.pos);
    const marker =
      target instanceof HTMLElement
        ? target
        : target?.parentElement instanceof HTMLElement
          ? target.parentElement
          : null;
    marker?.closest<HTMLElement>(".twyne-inline-note-reference")?.click();
  }
}

