import { describe, expect, test } from "bun:test";
import { InlineNoteNode } from "./inline-note-popover";
import { collectInlineNotes } from "../note-editing";
import { withEditor } from "../test-harness";

const CONTENT =
  '<p>A<sup data-endnote-text="Alpha" data-type="endnote"></sup> ' +
  'B<sup data-endnote-text="Beta" data-type="footnote"></sup></p>';

function dispatchKey(
  target: HTMLElement,
  key: string,
  window: typeof globalThis.window,
): void {
  target.dispatchEvent(
    new window.KeyboardEvent("keydown", { key, bubbles: true }),
  );
}

describe("inline note popover NodeView", () => {
  test("opens beside the reference with editing, kind, navigation, and delete controls", async () => {
    await withEditor(
      { content: CONTENT, extensions: [InlineNoteNode] },
      async ({ dom, host }) => {
        const marker = host.querySelector<HTMLElement>(
          ".twyne-inline-note-reference",
        )!;
        marker.click();

        const popover = dom.window.document.querySelector<HTMLElement>(
          "[data-inline-note-popover]",
        )!;
        await new Promise((resolve) => setTimeout(resolve, 0));
        expect(popover).toBeTruthy();
        expect(popover.style.position).toBe("fixed");
        expect(popover.querySelector('textarea[aria-label="Note text"]')).toBe(
          dom.window.document.activeElement,
        );
        expect(
          popover.querySelector('select[aria-label="Note kind"]'),
        ).toBeTruthy();
        expect(popover.querySelector("[data-note-previous]")).toBeTruthy();
        expect(popover.querySelector("[data-note-reference]")).toBeTruthy();
        expect(popover.querySelector("[data-note-next]")).toBeTruthy();
        expect(popover.querySelector("[data-note-delete]")).toBeTruthy();
      },
    );
  });

  test("typing edits the note immediately and kind conversion updates serialized HTML", async () => {
    await withEditor(
      { content: CONTENT, extensions: [InlineNoteNode] },
      ({ dom, editor, host }) => {
        host
          .querySelector<HTMLElement>(".twyne-inline-note-reference")!
          .click();
        const textarea = dom.window.document.querySelector<HTMLTextAreaElement>(
          'textarea[aria-label="Note text"]',
        )!;
        textarea.value = "Revised";
        textarea.dispatchEvent(
          new dom.window.Event("input", { bubbles: true }),
        );

        const select = dom.window.document.querySelector<HTMLSelectElement>(
          'select[aria-label="Note kind"]',
        )!;
        select.value = "footnote";
        select.dispatchEvent(new dom.window.Event("change", { bubbles: true }));

        expect(collectInlineNotes(editor.state.doc)[0]).toMatchObject({
          text: "Revised",
          kind: "footnote",
          number: 1,
        });
        expect(editor.getHTML()).toContain('data-endnote-text="Revised"');
        expect(editor.getHTML()).toContain('data-type="footnote"');
      },
    );
  });

  test("Escape closes the popover and returns focus to the note reference", async () => {
    await withEditor(
      { content: CONTENT, extensions: [InlineNoteNode] },
      ({ dom, editor, host }) => {
        const marker = host.querySelector<HTMLElement>(
          ".twyne-inline-note-reference",
        )!;
        marker.click();
        const textarea = dom.window.document.querySelector<HTMLTextAreaElement>(
          'textarea[aria-label="Note text"]',
        )!;

        dispatchKey(textarea, "Escape", dom.window);

        expect(
          dom.window.document.querySelector("[data-inline-note-popover]"),
        ).toBeNull();
        expect(dom.window.document.activeElement).toBe(marker);
        expect(editor.state.selection.constructor.name).toBe("NodeSelection");
      },
    );
  });

  test("Reference button returns to the marker and delete removes the note", async () => {
    await withEditor(
      { content: CONTENT, extensions: [InlineNoteNode] },
      ({ dom, editor, host }) => {
        const marker = host.querySelector<HTMLElement>(
          ".twyne-inline-note-reference",
        )!;
        marker.click();
        dom.window.document
          .querySelector<HTMLButtonElement>("[data-note-reference]")!
          .click();
        expect(dom.window.document.activeElement).toBe(marker);

        marker.click();
        dom.window.document
          .querySelector<HTMLButtonElement>("[data-note-delete]")!
          .click();
        expect(collectInlineNotes(editor.state.doc)).toHaveLength(1);
        expect(editor.getHTML()).not.toContain('data-endnote-text="Alpha"');
      },
    );
  });

  test("Next opens the adjacent note and updates navigation boundaries", async () => {
    await withEditor(
      { content: CONTENT, extensions: [InlineNoteNode] },
      ({ dom, host }) => {
        const markers = host.querySelectorAll<HTMLElement>(
          ".twyne-inline-note-reference",
        );
        markers[0]!.click();
        const previous = dom.window.document.querySelector<HTMLButtonElement>(
          "[data-note-previous]",
        )!;
        const next =
          dom.window.document.querySelector<HTMLButtonElement>(
            "[data-note-next]",
          )!;
        expect(previous.disabled).toBe(true);
        expect(next.disabled).toBe(false);

        next.click();

        const heading = dom.window.document.querySelector<HTMLElement>(
          "[data-note-heading]",
        )!;
        expect(heading.textContent).toBe("Footnote 1");
        expect(
          dom.window.document.querySelector<HTMLButtonElement>(
            "[data-note-previous]",
          )?.disabled,
        ).toBe(false);
        expect(
          dom.window.document.querySelector<HTMLButtonElement>(
            "[data-note-next]",
          )?.disabled,
        ).toBe(true);
      },
    );
  });
});

import {
  component$,
  noSerialize,
  useSignal,
  useStore,
  useVisibleTask$,
  type NoSerialize,
} from "@qwik.dev/core";
import type { Editor } from "@tiptap/core";
import type { Meta, StoryObj } from "storybook-framework-qwik";
import type { NotePopover, SelectionActionState } from "./editor-state";
import { SelectionActions } from "./selection-actions";
import { PersonaNotePanel } from "./persona-note-panel";
import {
  copyFixture,
  ModalCardStage,
  passage,
  personaNote,
} from "./modal-card.fixtures";

interface SelectionStoryProps {
  initial: "writing" | "selection" | "note";
  singleWord: boolean;
}

/** A real editable Tiptap range and persona mark; no persistence or AI calls. */
const ManuscriptSelectionPreview = component$<SelectionStoryProps>((props) => {
  const mount = useSignal<HTMLElement>();
  const editor = useSignal<NoSerialize<Editor>>();
  const state = useStore({
    selection: null as SelectionActionState | null,
    note: null as NotePopover | null,
    status:
      "Type in the manuscript, select a passage, or click the red button at the end of its persona mark.",
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ track, cleanup }) => {
    const initial = track(() => props.initial);
    const singleWord = track(() => props.singleWord);
    const [
      { Editor },
      { StarterKit },
      { PersonaNoteMark },
      { MarkAnchorWidgets },
    ] = await Promise.all([
      import("@tiptap/core"),
      import("@tiptap/starter-kit"),
      import("./extensions/persona-note-mark"),
      import("./extensions/mark-anchor-widgets"),
    ]);
    if (!mount.value) return;
    state.note = null;
    state.selection = null;
    const openNote = (anchor?: HTMLElement) => {
      const mark =
        anchor ??
        mount.value?.querySelector(
          ".twyne-mark-anchor[data-anchor-kind='note']",
        );
      if (!mark) return;
      const rect = mark.getBoundingClientRect();
      state.note = {
        ...copyFixture(personaNote),
        x: Math.max(12, Math.min(rect.right + 24, window.innerWidth - 364)),
        top: Math.max(96, Math.min(rect.top, window.innerHeight - 400)),
        maxH: Math.max(240, window.innerHeight - 120),
      };
      state.selection = null;
      state.status =
        "Persona note for the marked passage. The text remains editable.";
    };
    const instance = new Editor({
      element: mount.value,
      extensions: [StarterKit, PersonaNoteMark, MarkAnchorWidgets],
      content: {
        type: "doc",
        content: [
          {
            type: "paragraph",
            content: [
              {
                type: "text",
                text: passage,
                marks: [
                  {
                    type: "personaNote",
                    attrs: {
                      id: personaNote.id,
                      author: personaNote.author,
                      color: personaNote.color,
                      label: personaNote.label,
                      note: personaNote.note,
                      quote: passage,
                    },
                  },
                ],
              },
            ],
          },
          {
            type: "paragraph",
            content: [
              {
                type: "text",
                text: "At nine each morning, the doors opened to anyone who needed a chair. A student spread her notes beside the atlas. By the window, a man read yesterday’s newspaper.",
              },
            ],
          },
          {
            type: "paragraph",
            content: [
              {
                type: "text",
                text: "Continue the scene here, or select a few words to try the passage tools.",
              },
            ],
          },
        ],
      },
      editorProps: {
        attributes: {
          "aria-label": "Manuscript",
          role: "textbox",
          "aria-multiline": "true",
          style:
            "min-height: 18rem; outline: none; font: 1.1rem/1.8 var(--font-serif);",
        },
        handleClick: (_view, _pos, event) => {
          const target = event.target as Element;
          if (!target.closest("[data-persona-note-id], .twyne-mark-anchor"))
            state.note = null;
          return false;
        },
      },
      onSelectionUpdate: ({ editor: current }) => {
        const { from, to, empty } = current.state.selection;
        if (empty || state.note) {
          state.selection = null;
          return;
        }
        const start = current.view.coordsAtPos(from);
        const end = current.view.coordsAtPos(to);
        state.selection = {
          from,
          to,
          text: current.state.doc.textBetween(from, to, " "),
          x: Math.max(
            Math.min(300, window.innerWidth / 2),
            Math.min((start.left + end.right) / 2, window.innerWidth - 300),
          ),
          y: Math.max(88, start.top - 12),
          placement: "above",
          error: null,
        };
      },
    });
    // Match the editor shell: the chip opens the card; the text places the caret.
    const host = mount.value;
    const onAnchorClick = (event: MouseEvent) => {
      const chip = (event.target as Element).closest<HTMLElement>(
        ".twyne-mark-anchor[data-anchor-kind='note']",
      );
      if (!chip || chip.dataset.anchorId !== personaNote.id) return;
      event.preventDefault();
      openNote(chip);
    };
    host.addEventListener("click", onAnchorClick);
    editor.value = noSerialize(instance);
    if (initial === "selection")
      instance.commands.setTextSelection({
        from: 1,
        to: singleWord ? 4 : passage.length + 1,
      });
    if (initial === "note") {
      instance.commands.setTextSelection({ from: 1, to: passage.length + 1 });
      openNote();
    }
    instance.commands.focus();
    cleanup(() => {
      host.removeEventListener("click", onAnchorClick);
      instance.destroy();
      editor.value = undefined;
    });
  });

  return (
    <div
      onInput$={(event) => {
        const input = event.target as HTMLTextAreaElement;
        if (input.dataset.threadDraftKind === "note" && state.note)
          state.note.draft = input.value;
      }}
    >
      <ModalCardStage
        status={state.status}
        onReset$={() => {
          state.note = null;
          state.selection = null;
          editor.value?.commands.setTextSelection({
            from: 1,
            to: props.singleWord ? 4 : passage.length + 1,
          });
          editor.value?.commands.focus();
          state.status = "Marked passage selected. Edits stay in this preview.";
        }}
      >
        <article
          class="twyne-editor paper-sheet"
          style="max-width: 42rem; margin: 4rem 0 0; padding: 2rem;"
        >
          <h1 style="font: 1.75rem/1.3 var(--font-display); margin-bottom: 1.5rem;">
            The public room
          </h1>
          <div ref={mount} />
        </article>
        <SelectionActions
          selection={state.selection}
          onSentenceBench$={() => {
            state.status =
              "Compare a revision requested for the selected passage";
          }}
          onGetSources$={() => {
            state.status = "Find sources requested for the selected passage";
          }}
          onAddMargin$={() => {
            state.status = "Writer comment requested for the selected passage";
          }}
          onSendToPersona$={(_id, name) => {
            state.status = `Reading requested from ${name}. No provider call is made in this preview.`;
          }}
          onHear$={() => {
            state.status = "Read aloud requested for the selected passage";
          }}
          onThreads$={() => {
            state.status = "Threads requested for the selected passage";
          }}
          onTaskDesk$={() => {
            state.status = "Task desk requested for the selected passage";
          }}
          onSceneBench$={() => {
            state.status = "Scene bench requested for the selected passage";
          }}
          onClose$={() => {
            state.selection = null;
          }}
        />
        <PersonaNotePanel
          note={state.note}
          onPin$={() => {
            if (state.note) state.note.pinned = true;
          }}
          onClose$={() => {
            state.note = null;
          }}
          onStrike$={() => {
            state.note = null;
            state.status = "Note dismissed in preview";
          }}
          onReply$={(noteId, text) => {
            if (!state.note || !text.trim()) return;
            state.note.thread.push({
              id: `preview-${state.note.thread.length}`,
              noteId,
              author: "You",
              authorKind: "user",
              text,
              timestamp: Date.now(),
            });
            state.note.draft = "";
          }}
        />
      </ModalCardStage>
    </div>
  );
});

