          if (e.ctrlKey || e.metaKey || e.altKey) return;
          const k = e.key;
          const isPrintable = k.length === 1;
          if (
            !isPrintable &&
            k !== "Backspace" &&
            k !== "Delete" &&
            k !== "Enter"
