import type { AppError } from "../../types/application-errors";

export interface SpeechErrorView {
  title: string;
  message: string;
  retry: boolean;
  retryAfterSeconds?: number;
  recovery?: { label: string; href: string };
  /** Hint to switch voice or provider when the failure is provider-side. */
  suggestVoiceChange: boolean;
  /** Settings is the primary recovery; render it ahead of secondary actions. */
  primaryRecovery: boolean;
}

const TITLES: Partial<Record<AppError["code"], string>> = {
  AUTHENTICATION_REQUIRED: "Sign in to read aloud",
  AUTHENTICATION_FAILED: "Sign-in could not be verified",
  PERMISSION_DENIED: "Read aloud is unavailable",
  RATE_LIMITED: "The voice needs a moment",
  TIMEOUT: "The voice took too long",
  NETWORK_UNAVAILABLE: "Connection interrupted",
  CONFIGURATION_ERROR: "Voice setup needs attention",
  PROVIDER_ERROR: "The voice could not be prepared",
  MALFORMED_RESPONSE: "The audio could not be read",
};

/** Reviewed copy: hosted provider detail is never shown to the reader. */
export const HOSTED_NARRATION_FAILURE =
  "Hosted narration could not finish. Please try again later.";

/** Maps a structured error onto honest, actionable player copy. */
export function describeSpeechError(error: AppError | null): SpeechErrorView {
  if (!error) {
    return {
      title: "Read aloud stopped",
      message: "Narration failed.",
      retry: true,
      suggestVoiceChange: false,
      primaryRecovery: false,
    };
  }
  const downloadRequired = error.recovery.action === "download-required";
  let recovery: SpeechErrorView["recovery"];
  switch (error.recovery.action) {
    case "sign-in":
      recovery = { label: "Sign in", href: "/editor?auth=1" };
      break;
    case "check-configuration":
    case "choose-provider":
      recovery = { label: "Open voice settings", href: "/settings/" };
      break;
    case "download-required":
      recovery = { label: "Download in Settings", href: "/settings/" };
      break;
    default:
      break;
  }
  const hostedNarrationFailure =
    error.code === "PROVIDER_ERROR" && error.source === "convex";
  return {
    title: downloadRequired
      ? "Browser voice not downloaded"
      : (TITLES[error.code] ?? "Read aloud stopped"),
    message: downloadRequired
      ? "The browser voice isn't on this device yet. Download it in Settings (a few hundred MB), or pick a different voice. Nothing is downloaded automatically."
      : hostedNarrationFailure
        ? HOSTED_NARRATION_FAILURE
        : error.message.trim() || "Narration failed.",
    // Retrying cannot succeed until the voice has been downloaded.
    retry: error.recovery.canRetry && !downloadRequired,
    retryAfterSeconds:
      error.recovery.retryAfterMs === undefined
        ? undefined
        : Math.max(1, Math.ceil(error.recovery.retryAfterMs / 1000)),
    recovery,
    primaryRecovery: downloadRequired,
    // Provider failures are upstream: never imply the user's setup or key is
    // at fault. Only an unreadable audio response hints at trying another voice.
    suggestVoiceChange: error.code === "MALFORMED_RESPONSE",
  };
}

export type CopyStatus = "idle" | "copied" | "failed";

export function copyStatusMessage(status: CopyStatus): string {
  if (status === "copied") return "Reference copied.";
  if (status === "failed")
    return "Couldn't copy automatically. Select the reference and copy it.";
  return "";
}
import { describe, expect, test } from "bun:test";
import type { AppError } from "../../types/application-errors";
import {
  copyStatusMessage,
  describeSpeechError,
  HOSTED_NARRATION_FAILURE,
} from "./speech-error-model";

const base: AppError = {
  code: "PROVIDER_ERROR",
  message: "The selected provider could not complete the request.",
  referenceId: "err_1",
  source: "provider",
  recovery: { action: "retry", canRetry: true },
};

describe("describeSpeechError", () => {
  test("keeps the full message and offers retry only when retryable", () => {
    const v = describeSpeechError(base);
    expect(v.message).toBe(base.message);
    expect(v.retry).toBe(true);
    expect(v.suggestVoiceChange).toBe(false);
    expect(v.recovery).toBeUndefined();
    const none = describeSpeechError({
      ...base,
      recovery: { action: "none", canRetry: false },
    });
    expect(none.retry).toBe(false);
  });

  test("routes sign-in and settings recoveries", () => {
    expect(
      describeSpeechError({
        ...base,
        code: "AUTHENTICATION_REQUIRED",
        recovery: { action: "sign-in", canRetry: false },
      }).recovery?.href,
    ).toBe("/editor?auth=1");
    expect(
      describeSpeechError({
        ...base,
        code: "CONFIGURATION_ERROR",
        recovery: { action: "check-configuration", canRetry: false },
      }).recovery?.href,
    ).toBe("/settings/");
  });

  test("rounds retry-after up and handles a missing error", () => {
    expect(
      describeSpeechError({
        ...base,
        recovery: { action: "retry-later", canRetry: true, retryAfterMs: 1200 },
      }).retryAfterSeconds,
    ).toBe(2);
    expect(describeSpeechError(null).message).toBe("Narration failed.");
  });

  test("explains download-required without implying an outage", () => {
    const v = describeSpeechError({
      ...base,
      code: "CONFIGURATION_ERROR",
      recovery: { action: "download-required", canRetry: false },
    });
    expect(v.title).toBe("Browser voice not downloaded");
    expect(v.message).toContain("Nothing is downloaded automatically");
    expect(v.recovery?.href).toBe("/settings/");
    expect(v.suggestVoiceChange).toBe(false);
  });

  test("permission denied does not invent a cause", () => {
    const v = describeSpeechError({
      ...base,
      code: "PERMISSION_DENIED",
      recovery: { action: "none", canRetry: false },
    });
    expect(v.title).toBe("Read aloud is unavailable");
    expect(v.title.toLowerCase()).not.toContain("plan");
  });

  test("download-required suppresses retry even if canRetry is set", () => {
    const v = describeSpeechError({
      ...base,
      code: "CONFIGURATION_ERROR",
      recovery: { action: "download-required", canRetry: true },
    });
    expect(v.retry).toBe(false);
    expect(v.primaryRecovery).toBe(true);
    expect(describeSpeechError(base).primaryRecovery).toBe(false);
  });

  test("copy status messages are visible text for failure and success", () => {
    expect(copyStatusMessage("idle")).toBe("");
    expect(copyStatusMessage("copied")).toContain("copied");
    expect(copyStatusMessage("failed")).toContain("Select the reference");
  });

  test("hosted convex provider failures use reviewed copy, not raw detail", () => {
    const raw =
      'HTTP 500 {"error":"upstream","api_key":"sk-secret-123","trace":"at gateway.ts:42"}';
    const v = describeSpeechError({
      ...base,
      source: "convex",
      message: raw,
      referenceId: "err_hosted",
    });
    expect(v.message).toBe(HOSTED_NARRATION_FAILURE);
    expect(JSON.stringify(v)).not.toContain("sk-secret-123");
    expect(v.retry).toBe(true);
    expect(v.recovery).toBeUndefined();
  });

  test("other providers' classified messages are unchanged", () => {
    const v = describeSpeechError({ ...base, source: "provider" });
    expect(v.message).toBe(base.message);
  });
});
import { component$, useStore, type PropFunction } from "@qwik.dev/core";
import { Link } from "@qwik.dev/router";
import type { AppError } from "../../types/application-errors";
import {
  copyStatusMessage,
